        if len(frac_part) > 4:
            raise ValueError("More than 4 decimal places")
        frac_part = frac_part.ljust(4, '0')
        val = int(int_part + frac_part) * sign
    else:
        val = int(text) * sign

    return val


def format(value: int) -> str:
    if value < 0:
        return f"-{format(-value)}"
    int_part = value // SCALE
    frac_part = value % SCALE
    return f"{int_part}.{frac_part:04d}"


def add(a: int, b: int) -> int:
    return a + b


def sub(a: int, b: int) -> int:
    return a - b


def mul(a: int, b: int) -> int:
    x = a * b
    sign = 1 if x >= 0 else -1
    return sign * ((abs(x) + SCALE // 2) // SCALE)


