        raise ZeroDivisionError("division by zero")
    num = a * SCALE
    sign = 1 if (a >= 0) == (b >= 0) else -1
    return sign * ((abs(num) + abs(b) // 2) // abs(b))


def to_float(value: int) -> float:
    return value / SCALE
