def merge(intervals):
    """Sort by start, then merge intervals that overlap or merely touch. Drops zero-length intervals."""
    valid = [(s, e) for s, e in intervals if s < e]
    if not valid:
        return []

    # Check for invalid intervals
    for s, e in intervals:
        if s > e:
            raise ValueError("start > end")

    valid.sort(key=lambda x: (x[0], -x[1]))

    merged = [valid[0]]
    for curr in valid[1:]:
        last = merged[-1]
        if curr[0] <= last[1]:
            merged[-1] = (last[0], max(last[1], curr[1]))
        else:
            merged.append(curr)
    return merged


def intersect(a, b):
    """Every non-empty overlap of an interval in a with one in b, merged."""
    ma = merge(a)
    mb = merge(b)
    res = []
    i, j = 0, 0
    while i < len(ma) and j < len(mb):
        sa, ea = ma[i]
        sb, eb = mb[j]
        s = max(sa, sb)
        e = min(ea, eb)
        if s < e:
            res.append((s, e))
        if ea <= eb:
            i += 1
        else:
            j += 1
    return res


def subtract(a, b):
    """The parts of a not covered by b, merged."""
    mb = merge(b)
    res = []
    for sa, ea in a:
        current = [(sa, ea)]
        for sb, eb in mb:
            next_current = []
            for cs, ce in current:
                if eb <= cs or sb >= ce:
                    next_current.append((cs, ce))
                else:
                    if cs < sb:
                        next_current.append((cs, sb))
                    if eb < ce:
                        next_current.append((eb, ce))
            current = next_current
        res.extend(current)
    return merge(res)


def coverage(intervals):
    """Total length covered, counting overlaps once."""
    return sum(e - s for s, e in merge(intervals))


def contains(intervals, point):
    """True when the point falls in any interval, honouring the half-open rule."""
    for s, e in intervals:
        if s <= point < e:
            return True
    return False
