import re

def _is_digits(s):
    return bool(re.fullmatch(r'[0-9]+', s))

def parse(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    text = text.strip()
    if text.startswith('v'):
        text = text[1:]

    build = ()
    if '+' in text:
        core_and_pre, build_str = text.split('+', 1)
        if not build_str:
            raise ValueError("empty build section")
        build = tuple(build_str.split('.'))
    else:
        core_and_pre = text

    prerelease = ()
    if '-' in core_and_pre:
        core, pre_str = core_and_pre.split('-', 1)
        if not pre_str:
            raise ValueError("empty prerelease section")
        prerelease = tuple(pre_str.split('.'))
    else:
        core = core_and_pre

    parts = core.split('.')
    if len(parts) != 3:
        raise ValueError("missing parts")

    major_s, minor_s, patch_s = parts

    def check_num(s):
        if not _is_digits(s):
            raise ValueError(f"non-numeric core part: {s}")
        if len(s) > 1 and s[0] == '0':
            raise ValueError(f"leading zero in {s}")
        return int(s)

    major = check_num(major_s)
    minor = check_num(minor_s)
    patch = check_num(patch_s)

    for ident in prerelease:
        if not ident:
            raise ValueError("empty prerelease identifier")
        if _is_digits(ident):
            if len(ident) > 1 and ident[0] == '0':
                raise ValueError(f"leading zero in prerelease identifier: {ident}")

    return (major, minor, patch, prerelease, build)

def _compare_prerelease(pre_a, pre_b):
    for id_a, id_b in zip(pre_a, pre_b):
        a_is_num = _is_digits(id_a)
        b_is_num = _is_digits(id_b)

        if a_is_num and b_is_num:
            num_a, num_b = int(id_a), int(id_b)
            if num_a < num_b: return -1
            if num_a > num_b: return 1
        elif a_is_num:
            return -1
        elif b_is_num:
            return 1
        else:
            if id_a < id_b: return -1
            if id_a > id_b: return 1

    if len(pre_a) < len(pre_b): return -1
    if len(pre_a) > len(pre_b): return 1
    return 0

def compare(a, b):
    pa = parse(a) if isinstance(a, str) else a
    pb = parse(b) if isinstance(b, str) else b

    for i in range(3):
        if pa[i] < pb[i]: return -1
        if pa[i] > pb[i]: return 1

    pre_a, pre_b = pa[3], pb[3]

    if not pre_a and not pre_b: return 0
    if pre_a and not pre_b: return -1
    if not pre_a and pre_b: return 1

    return _compare_prerelease(pre_a, pre_b)

def satisfies(version, spec):
    v = parse(version) if isinstance(version, str) else version
    comparators = spec.split()

    for comp in comparators:
        if comp.startswith('^'):
            ver = parse(comp[1:])
            if compare(v, ver) < 0: return False
            upper = (ver[0] + 1, 0, 0, (), ())
            if compare(v, upper) >= 0: return False
        elif comp.startswith('~'):
            ver = parse(comp[1:])
            if compare(v, ver) < 0: return False
            upper = (ver[0], ver[1] + 1, 0, (), ())
            if compare(v, upper) >= 0: return False
        else:
            op = None
            ver_str = None
            for o in ['>=', '<=', '==', '=', '>', '<']:
                if comp.startswith(o):
                    op = o
                    ver_str = comp[len(o):]
                    break
            if op is None:
                raise ValueError(f"Unknown comparator: {comp}")
            ver = parse(ver_str)

            c = compare(v, ver)
            if op == '>=' and c < 0: return False
            if op == '<=' and c > 0: return False
            if op == '>' and c <= 0: return False
            if op == '<' and c >= 0: return False
            if op in ('=', '==') and c != 0: return False

    return True
