import math


def mean(xs):
    if not xs:
        raise ValueError("empty sequence")
    return sum(xs) / len(xs)


def median(xs):
    if not xs:
        raise ValueError("empty sequence")
    s = sorted(xs)
    n = len(s)
    mid = n // 2
    if n % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2.0
    return float(s[mid])


def variance(xs, sample=False):
    if not xs:
        raise ValueError("empty sequence")
    if sample and len(xs) < 2:
        raise ValueError("sample variance requires at least 2 values")
    m = mean(xs)
    n = len(xs)
    ss = sum((x - m) ** 2 for x in xs)
    return ss / (n if not sample else n - 1)


def stdev(xs, sample=False):
    return math.sqrt(variance(xs, sample=sample))


def percentile(xs, p):
    if not xs:
        raise ValueError("empty sequence")
    if p < 0 or p > 100:
        raise ValueError("p must be between 0 and 100")
    s = sorted(xs)
    n = len(s)
    k = (n - 1) * p / 100.0
    f = math.floor(k)
    c = math.ceil(k)
    if f == c:
        return float(s[int(k)])
    return s[int(f)] + (s[int(c)] - s[int(f)]) * (k - f)


def mode(xs):
    if not xs:
        raise ValueError("empty sequence")
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    candidates = [x for x, c in counts.items() if c == max_count]
    return min(candidates)


def normalize(xs):
    m = mean(xs)
    s = stdev(xs, sample=False)
    if s == 0:
        return [0.0] * len(xs)
    return [(x - m) / s for x in xs]


def covariance(xs, ys, sample=False):
    if len(xs) != len(ys):
        raise ValueError("sequences must have same length")
    if not xs:
        raise ValueError("empty sequence")
    if sample and len(xs) < 2:
        raise ValueError("sample covariance requires at least 2 values")
    n = len(xs)
    mx = mean(xs)
    my = mean(ys)
    ss = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    return ss / (n if not sample else n - 1)


def correlation(xs, ys):
    s_x = stdev(xs, sample=False)
    s_y = stdev(ys, sample=False)
    if s_x == 0 or s_y == 0:
        return 0.0
    return covariance(xs, ys) / (s_x * s_y)
