def _is_numeric(s):
    return s.isdigit()


def compare(a, b):
    for i in range(3):
        if a[i] < b[i]: return -1
        if a[i] > b[i]: return 1

    pre_a = a[3]
    pre_b = b[3]

    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    for i in range(min(len(pre_a), len(pre_b))):
        id_a = pre_a[i]
        id_b = pre_b[i]
        num_a = _is_numeric(id_a)
        num_b = _is_numeric(id_b)

        if num_a and num_b:
            val_a, val_b = int(id_a), int(id_b)
            if val_a < val_b: return -1
            if val_a > val_b: return 1
        elif num_a:
            return -1
        elif num_b:
            return 1
        else:
            if id_a < id_b: return -1
            if id_a > id_b: return 1

    if len(pre_a) < len(pre_b): return -1
    if len(pre_a) > len(pre_b): return 1
    return 0


def satisfies(version, spec):
    if isinstance(version, str):
        version = parse(version)

    for comp in spec.split():
        if not comp: continue

        if comp.startswith('^'):
            base = parse(comp[1:])
            if compare(version, base) < 0: return False
            upper = (base[0] + 1, 0, 0, (), ())
            if compare(version, upper) >= 0: return False
        elif comp.startswith('~'):
            base = parse(comp[1:])
            if compare(version, base) < 0: return False
            upper = (base[0], base[1] + 1, 0, (), ())
            if compare(version, upper) >= 0: return False
        else:
            op = None
            ver_str = None
            for o in ['>=', '<=', '==', '=', '>', '<']:
                if comp.startswith(o):
                    op = o
                    ver_str = comp[len(o):]
                    break
            if op is None:
                raise ValueError(f"Unknown comparator: {comp}")
            ver = parse(ver_str)
            cmp = compare(version, ver)
            if op == '>=' and cmp < 0: return False
            if op == '<=' and cmp > 0: return False
            if op == '>' and cmp <= 0: return False
            if op == '<' and cmp >= 0: return False
            if op in ('=', '==') and cmp != 0: return False

