        pre_part = rest[1:]
        plus_idx = pre_part.find('+')
        if plus_idx != -1:
            build_str = pre_part[plus_idx+1:]
            pre_part = pre_part[:plus_idx]

        if not pre_part:
            raise ValueError("Empty prerelease section")
        prerelease = tuple(pre_part.split('.'))
        for p in prerelease:
            if not p:
                raise ValueError("Empty prerelease identifier")

        if plus_idx != -1:
            if not build_str:
                raise ValueError("Empty build section")
            build = tuple(build_str.split('.'))
    elif rest.startswith('+'):
        build_str = rest[1:]
        if not build_str:
            raise ValueError("Empty build section")
        build = tuple(build_str.split('.'))
    elif rest:
        raise ValueError("Invalid version string")

    return (major, minor, patch, prerelease, build)


