    va = _to_tuple(a)
    vb = _to_tuple(b)

    # Compare major, minor, patch numerically
    for i in range(3):
        if va[i] < vb[i]: return -1
        if va[i] > vb[i]: return 1

    # Prerelease comparison
    pre_a = va[3]
    pre_b = vb[3]

    # No prerelease has higher precedence than with prerelease
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    # Both have prerelease
    for i in range(min(len(pre_a), len(pre_b))):
        id_a = pre_a[i]
        id_b = pre_b[i]

        a_is_num = id_a.isdigit()
        b_is_num = id_b.isdigit()

        if a_is_num and b_is_num:
            na, nb = int(id_a), int(id_b)
            if na < nb: return -1
            if na > nb: return 1
        elif a_is_num:
            # numeric always lower than alphanumeric
            return -1
        elif b_is_num:
            return 1
        else:
            # both alphanumeric, compare ASCII order
            if id_a < id_b: return -1
            if id_a > id_b: return 1

