"""Exact decimal arithmetic for money using scaled integers (SCALE = 10000)."""

SCALE = 10000


def parse(text):
    """Convert a decimal string to a scaled integer.

    Accepts optional leading +/-, at most one dot, and at most 4 decimal places.
    Raises ValueError on anything else.
    """
    if not text:
        raise ValueError("empty string")

    s = text
    sign = 1
    if s[0] in ('+', '-'):
        if s[0] == '-':
            sign = -1
        s = s[1:]

    if not s:
        raise ValueError("no digits after sign")

    dot_count = s.count('.')
    if dot_count > 1:
        raise ValueError("more than one dot")

    if dot_count == 1:
        int_part, frac_part = s.split('.')
        if len(frac_part) > 4:
            raise ValueError("more than 4 decimal places")
        all_chars = int_part + frac_part
        if not all_chars or not all(c.isdigit() for c in all_chars):
            raise ValueError("invalid characters")
        value = int(int_part or '0') * SCALE + int(frac_part.ljust(4, '0'))
    else:
        if not all(c.isdigit() for c in s):
            raise ValueError("invalid characters")
        value = int(s) * SCALE

    return sign * value


def format(value):
    """Convert a scaled integer to a string with exactly 4 decimal places."""
    neg = value < 0
    v = abs(value)
    int_part = v // SCALE
    frac_part = v % SCALE
    s = f"{int_part}.{frac_part:04d}"
    return "-" + s if neg else s


def add(a, b):
    """Scaled-integer addition."""
    return a + b


def sub(a, b):
    """Scaled-integer subtraction."""
    return a - b


def _round_half_away_from_zero(numerator, denominator):
    """Round numerator/denominator to nearest int, halves away from zero.

    Both arguments are non-negative; caller handles sign.
    """
    q, r = divmod(numerator, denominator)
    if 2 * r > denominator or 2 * r == denominator:
        q += 1
    return q


def mul(a, b):
    """Exact product rounded to nearest scaled integer, halves away from zero."""
    product = a * b
    if product >= 0:
        return _round_half_away_from_zero(product, SCALE)
    else:
        # For negative: divmod gives floor quotient and non-negative remainder.
        # Away from zero means toward more negative on a tie.
        q, r = divmod(-product, SCALE)
        if 2 * r > SCALE:
            q += 1
        return -q


def div(a, b):
    """Exact quotient rounded to nearest scaled integer, halves away from zero."""
    if b == 0:
        raise ZeroDivisionError("division by zero")
    numerator = a * SCALE
    if numerator >= 0:
        return _round_half_away_from_zero(numerator, b)
    else:
        q, r = divmod(-numerator, b)
        if 2 * r > b:
            q += 1
        return -q


def to_float(value):
    """The value as a Python float."""
    return value / SCALE
