"""Semantic Versioning 2.0.0 parsing and comparison."""


def parse(text):
    """Parse a semver string into (major, minor, patch, prerelease, build)."""
    if not isinstance(text, str):
        raise ValueError("input must be a string")

    s = text.strip()
    if s.startswith('v'):
        s = s[1:]

    # Split off build metadata
    if '+' in s:
        core_part, build_str = s.split('+', 1)
    else:
        core_part, build_str = s, None

    # Split off prerelease
    if '-' in core_part:
        version_part, prerelease_str = core_part.split('-', 1)
    else:
        version_part, prerelease_str = core_part, None

    # Parse major.minor.patch
    parts = version_part.split('.')
    if len(parts) != 3:
        raise ValueError(f"expected 3 dot-separated parts, got {len(parts)}")

    for part in parts:
        if not part:
            raise ValueError("empty version component")
        if not part.isdigit():
            raise ValueError(f"non-numeric core part: {part!r}")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"leading zero in: {part!r}")

    major = int(parts[0])
    minor = int(parts[1])
    patch = int(parts[2])

    # Parse prerelease
    if prerelease_str is not None:
        if prerelease_str == '':
            raise ValueError("empty prerelease section")
        identifiers = prerelease_str.split('.')
        for ident in identifiers:
            if ident == '':
                raise ValueError("empty prerelease identifier")
        prerelease = tuple(identifiers)
    else:
        prerelease = ()

    # Parse build
    if build_str is not None:
        if build_str == '':
            raise ValueError("empty build section")
        identifiers = build_str.split('.')
        for ident in identifiers:
            if ident == '':
                raise ValueError("empty build identifier")
        build = tuple(identifiers)
    else:
        build = ()

    return (major, minor, patch, prerelease, build)


def _compare_identifiers(a, b):
    """Compare two prerelease identifiers per semver rules."""
    a_numeric = a.isdigit()
    b_numeric = b.isdigit()

    if a_numeric and b_numeric:
        ia, ib = int(a), int(b)
        if ia < ib:
            return -1
        if ia > ib:
            return 1
        return 0
    elif a_numeric and not b_numeric:
        return -1
    elif not a_numeric and b_numeric:
        return 1
    else:
        if a < b:
            return -1
        if a > b:
            return 1
        return 0


def compare(a, b):
    """Compare two parsed versions. Returns -1, 0, or 1."""
    # Compare major, minor, patch numerically
    for i in range(3):
        if a[i] < b[i]:
            return -1
        if a[i] > b[i]:
            return 1

    # Prerelease precedence: having one means lower precedence
    if a[3] and not b[3]:
        return -1
    if not a[3] and b[3]:
        return 1
    if not a[3] and not b[3]:
        return 0

    # Both have prerelease: compare identifiers left to right
    for ia, ib in zip(a[3], b[3]):
        c = _compare_identifiers(ia, ib)
        if c != 0:
            return c

    # All shared identifiers equal; longer list wins
    if len(a[3]) < len(b[3]):
        return -1
    if len(a[3]) > len(b[3]):
        return 1
    return 0


def satisfies(version, spec):
    """Check whether a parsed version satisfies all comparators in spec."""
    comparators = spec.split()
    for comp in comparators:
        if not _check_comparator(version, comp):
            return False
    return True


def _check_comparator(version, comp):
    if comp.startswith('>='):
        target = parse(comp[2:])
        return compare(version, target) >= 0
    elif comp.startswith('<='):
        target = parse(comp[2:])
        return compare(version, target) <= 0
    elif comp.startswith('>'):
        target = parse(comp[1:])
        return compare(version, target) > 0
    elif comp.startswith('<'):
        target = parse(comp[1:])
        return compare(version, target) < 0
    elif comp.startswith('=='):
        target = parse(comp[2:])
        return compare(version, target) == 0
    elif comp.startswith('='):
        target = parse(comp[1:])
        return compare(version, target) == 0
    elif comp.startswith('^'):
        target = parse(comp[1:])
        major, minor, patch = target[0], target[1], target[2]
        if compare(version, target) < 0:
            return False
        upper = (major + 1, 0, 0, (), ())
        if compare(version, upper) >= 0:
            return False
        return True
    elif comp.startswith('~'):
        target = parse(comp[1:])
