import math


def mean(xs):
    if not xs:
        raise ValueError("empty input")
    return sum(xs) / len(xs)


def median(xs):
    if not xs:
        raise ValueError("empty input")
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        return float(s[n // 2])
    return (s[n // 2 - 1] + s[n // 2]) / 2.0


def variance(xs, sample=False):
    if not xs:
        raise ValueError("empty input")
    if sample and len(xs) < 2:
        raise ValueError("sample variance requires at least 2 values")
    n = len(xs)
    m = mean(xs)
    ss = sum((x - m) ** 2 for x in xs)
    divisor = (n - 1) if sample else n
    return ss / divisor


def stdev(xs, sample=False):
    return math.sqrt(variance(xs, sample=sample))


def percentile(xs, p):
    if not xs:
        raise ValueError("empty input")
    if p < 0 or p > 100:
        raise ValueError("p must be in 0..100")
    s = sorted(xs)
    n = len(s)
    k = (n - 1) * p / 100.0
    lo = int(math.floor(k))
    hi = int(math.ceil(k))
    if lo == hi:
        return float(s[lo])
    frac = k - lo
    return s[lo] + frac * (s[hi] - s[lo])


def mode(xs):
    if not xs:
        raise ValueError("empty input")
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    candidates = [x for x, c in counts.items() if c == max_count]
    return min(candidates)


def normalize(xs):
    if not xs:
        raise ValueError("empty input")
    m = mean(xs)
    s = stdev(xs)
    if s == 0:
        return [0.0 for _ in xs]
    return [(x - m) / s for x in xs]


def covariance(xs, ys, sample=False):
    if not xs or not ys:
        raise ValueError("empty input")
    if len(xs) != len(ys):
        raise ValueError("mismatched lengths")
    if sample and len(xs) < 2:
        raise ValueError("sample covariance requires at least 2 values")
    n = len(xs)
    mx = mean(xs)
    my = mean(ys)
    ss = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    divisor = (n - 1) if sample else n
    return ss / divisor


def correlation(xs, ys):
    if not xs or not ys:
        raise ValueError("empty input")
    if len(xs) != len(ys):
        raise ValueError("mismatched lengths")
    sx = stdev(xs)
    sy = stdev(ys)
    if sx == 0 or sy == 0:
        return 0.0
    return covariance(xs, ys) / (sx * sy)
