import re


def parse(text):
    """Parse CSV text into a list of rows (each a list of strings)."""
    if not text:
        return []

    rows = []
    i = 0
    n = len(text)

    while i < n:
        fields = []
        while True:
            if i < n and text[i] == '"':
                # Quoted field
                i += 1
                buf = []
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        buf.append(text[i])
                        i += 1
                fields.append(''.join(buf))
            else:
                # Unquoted field
                buf = []
                while i < n and text[i] != ',' and text[i] != '\n' and not (text[i] == '\r' and i + 1 < n and text[i + 1] == '\n'):
                    buf.append(text[i])
                    i += 1
                fields.append(''.join(buf))

            if i < n and text[i] == ',':
                i += 1
            else:
                break

        # Consume line ending
        if i < n and text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
            i += 2
        elif i < n and text[i] == '\n':
            i += 1

        rows.append(fields)

    return rows


def format(rows):
    """Format a list of rows back into CSV text."""
    if not rows:
        return ""

    def fmt_field(f):
        if f == "":
