"""Exact decimal arithmetic for money using scaled integers.

SCALE = 10000 (4 decimal places). A value is stored as an integer equal to
the real value times 10000. For example 12.3456 is stored as 123456.
"""

SCALE = 10000


def parse(text):
    """Decimal string to scaled integer.

    Accepts an optional leading +/-, an optional single ., and at most 4
    decimal places. Raises ValueError on anything else.
    """
    if not text:
        raise ValueError("empty string")

    s = text
    sign = 1
    if s[0] in ('+', '-'):
        if s[0] == '-':
            sign = -1
        s = s[1:]

    if not s:
        raise ValueError("no digits after sign")

    dot_count = s.count('.')
    if dot_count > 1:
        raise ValueError("more than one dot")

    if dot_count == 1:
        int_part, frac_part = s.split('.')
        if len(frac_part) > 4:
            raise ValueError("more than 4 decimal places")
        all_chars = int_part + frac_part
        if not all_chars or not all(c.isdigit() for c in all_chars):
            raise ValueError("non-digit character")
        value = int(int_part or '0') * SCALE + int(frac_part.ljust(4, '0'))
    else:
        if not all(c.isdigit() for c in s):
            raise ValueError("non-digit character")
        value = int(s) * SCALE

    return sign * value


def format(value):
    """Scaled integer back to a string with exactly 4 decimal places."""
    neg = value < 0
    v = abs(value)
    int_part = v // SCALE
    frac_part = v % SCALE
    s = f"{int_part}.{frac_part:04d}"
    return "-" + s if neg else s


def add(a, b):
    """Scaled-integer addition."""
    return a + b


def sub(a, b):
    """Scaled-integer subtraction."""
    return a - b


def _round_half_away_from_zero(numerator, denominator):
    """Round numerator/denominator to nearest int, halves away from zero.

    Both arguments are non-negative; the caller handles sign.
    """
    q, r = divmod(numerator, denominator)
    if 2 * r >= denominator:
        q += 1
    return q


def mul(a, b):
    """Exact product rounded to nearest scaled integer, halves away from zero."""
    product = a * b
    if product >= 0:
        return _round_half_away_from_zero(product, SCALE)
    else:
        return -_round_half_away_from_zero(-product, SCALE)


def div(a, b):
    """Exact quotient rounded to nearest scaled integer, halves away from zero.

    Raises ZeroDivisionError when b == 0.
    """
    if b == 0:
