def parse(text):
    """Parse a semver string into (major, minor, patch, prerelease, build)."""
    if not isinstance(text, str):
        raise ValueError("Expected a string")

    s = text.strip()
    if s.startswith('v'):
        s = s[1:]

    # Split off build metadata
    if '+' in s:
        s, build_str = s.split('+', 1)
    else:
        build_str = None

    # Split off prerelease (first '-' after the numeric core)
    if '-' in s:
        idx = s.index('-')
        core_str = s[:idx]
        prerelease_str = s[idx + 1:]
    else:
        core_str = s
        prerelease_str = None

    # Parse major.minor.patch
    parts = core_str.split('.')
    if len(parts) != 3:
        raise ValueError(f"Expected major.minor.patch, got '{core_str}'")

    for part in parts:
        if not part.isdigit():
            raise ValueError(f"Non-numeric core part: '{part}'")
        if len(part) > 1 and part[0] == '0':
            raise ValueError(f"Leading zero in core part: '{part}'")

    major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

    # Parse prerelease identifiers
    if prerelease_str is not None:
        if prerelease_str == '':
            raise ValueError("Empty prerelease section")
        pre_ids = prerelease_str.split('.')
        for pid in pre_ids:
            if pid == '':
                raise ValueError("Empty prerelease identifier")
            if not all(c.isdigit() or c.isalpha() or c == '-' for c in pid):
                raise ValueError(f"Invalid prerelease identifier: '{pid}'")
        prerelease = tuple(pre_ids)
    else:
        prerelease = ()

    # Parse build identifiers
    if build_str is not None:
        if build_str == '':
            raise ValueError("Empty build section")
        build_ids = build_str.split('.')
        for bid in build_ids:
            if bid == '':
                raise ValueError("Empty build identifier")
            if not all(c.isdigit() or c.isalpha() or c == '-' for c in bid):
                raise ValueError(f"Invalid build identifier: '{bid}'")
        build = tuple(build_ids)
    else:
        build = ()

    return (major, minor, patch, prerelease, build)


def compare(a, b):
    """Compare two parsed versions. Returns -1, 0, or 1."""
    # Compare major, minor, patch numerically
    for i in range(3):
        if a[i] < b[i]:
            return -1
        if a[i] > b[i]:
            return 1

    pa, pb = a[3], b[3]

    # No prerelease on either
    if not pa and not pb:
        return 0
    # a has no prerelease, b does -> a is higher
    if not pa and pb:
        return 1
    # a has prerelease, b does not -> a is lower
    if pa and not pb:
        return -1

    # Both have prerelease: compare identifier by identifier
    for ia, ib in zip(pa, pb):
        ia_num = ia.isdigit()
        ib_num = ib.isdigit()

        if ia_num and ib_num:
            if int(ia) < int(ib):
                return -1
            if int(ia) > int(ib):
                return 1
        elif ia_num and not ib_num:
            # numeric always ranks lower than alphanumeric
            return -1
        elif not ia_num and ib_num:
            return 1
        else:
            # both alphanumeric: ASCII order
            if ia < ib:
                return -1
            if ia > ib:
                return 1

    # All shared identifiers equal; longer prerelease wins
    if len(pa) < len(pb):
        return -1
    if len(pa) > len(pb):
        return 1
    return 0


