    if not isinstance(text, str) or len(text) == 0:
        raise ValueError("empty or non-string input")

    s = text
    sign = 1
    if s[0] in ('+', '-'):
        if s[0] == '-':
            sign = -1
        s = s[1:]

    if len(s) == 0:
        raise ValueError("no digits")

    dot_count = s.count('.')
    if dot_count > 1:
        raise ValueError("more than one dot")

    if dot_count == 1:
        idx = s.index('.')
        int_part = s[:idx]
        frac_part = s[idx + 1:]
        if len(frac_part) > 4:
            raise ValueError("more than 4 decimal places")
        digits = int_part + frac_part
    else:
        digits = s

    if len(digits) == 0:
        raise ValueError("no digits")
    if not digits.isdigit():
        raise ValueError("non-digit characters")

    value = int(digits)
    if dot_count == 1:
        n_frac = len(s) - s.index('.') - 1
        value *= 10 ** (4 - n_frac)

    return sign * value


