    """Exact product rounded to the nearest scaled integer (halves away from zero)."""
    return _round_half_away(a * b, SCALE)


def div(a, b):
    """Exact quotient rounded to the nearest scaled integer (halves away from zero).

    Raises ZeroDivisionError when b == 0.
    """
    if b == 0:
        raise ZeroDivisionError("division by zero")
    return _round_half_away(a * SCALE, b)


def to_float(value):
    """Return the value as a Python float."""
