"""Half-open interval arithmetic. Every interval is (start, end) representing [start, end)."""


def merge(intervals):
    """Sort by start, then merge intervals that overlap or merely touch.
    A zero-length interval (start == end) is dropped.
    Raises ValueError if start > end. Returns a sorted list of tuples."""
    filtered = []
    for s, e in intervals:
        if s > e:
            raise ValueError("start > end")
        if s == e:
            continue
        filtered.append((s, e))

    if not filtered:
        return []

    filtered.sort()
    result = [filtered[0]]
    for s, e in filtered[1:]:
        prev_s, prev_e = result[-1]
        if s <= prev_e:
            result[-1] = (prev_s, max(prev_e, e))
        else:
            result.append((s, e))
    return result


def intersect(a, b):
    """Every non-empty overlap of an interval in a with one in b, merged."""
    merged_a = merge(a)
    merged_b = merge(b)

    overlaps = []
    for s1, e1 in merged_a:
        for s2, e2 in merged_b:
            lo = max(s1, s2)
            hi = min(e1, e2)
            if lo < hi:
                overlaps.append((lo, hi))

    return merge(overlaps)


def subtract(a, b):
    """The parts of a not covered by b, merged."""
    merged_a = merge(a)
    merged_b = merge(b)

    result = []
    for s, e in merged_a:
        remaining = [(s, e)]
        for bs, be in merged_b:
            new_remaining = []
            for rs, re in remaining:
                if be <= rs or bs >= re:
                    new_remaining.append((rs, re))
                else:
                    if bs > rs:
                        new_remaining.append((rs, bs))
                    if be < re:
                        new_remaining.append((be, re))
            remaining = new_remaining
        result.extend(remaining)

    return merge(result)


def coverage(intervals):
    """Total length covered, counting overlaps once."""
    merged = merge(intervals)
    return sum(e - s for s, e in merged)


def contains(intervals, point):
    """True when the point falls in any interval, honouring the half-open rule."""
    for s, e in intervals:
        if s <= point < e:
            return True
    return False
