import re


def parse(text):
    """Parse a semver string into (major, minor, patch, prerelease, build)."""
    if not isinstance(text, str):
        raise ValueError("expected a string")

    s = text
    if s.startswith('v'):
        s = s[1:]

    m = re.match(r'^(\d+)\.(\d+)\.(\d+)(?:-([^-+]+))?(?:\+([^+]*))?$', s)
    if not m:
        raise ValueError(f"invalid semver string: {text!r}")

    major_s, minor_s, patch_s = m.group(1), m.group(2), m.group(3)
    prerelease_s = m.group(4)
    build_s = m.group(5)

    for name, val in (('major', major_s), ('minor', minor_s), ('patch', patch_s)):
        if len(val) > 1 and val[0] == '0':
            raise ValueError(f"leading zero in {name}")

    major, minor, patch = int(major_s), int(minor_s), int(patch_s)

    prerelease = ()
    if prerelease_s is not None:
        if prerelease_s == '':
            raise ValueError("empty prerelease section")
        ids = prerelease_s.split('.')
        for ident in ids:
            if ident == '':
                raise ValueError("empty prerelease identifier")
            if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                raise ValueError(f"invalid prerelease identifier: {ident!r}")
        prerelease = tuple(ids)

    build = ()
    if build_s is not None:
        if build_s == '':
            raise ValueError("empty build section")
        ids = build_s.split('.')
        for ident in ids:
            if ident == '':
                raise ValueError("empty build identifier")
            if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                raise ValueError(f"invalid build identifier: {ident!r}")
        build = tuple(ids)

    return (major, minor, patch, prerelease, build)


def _is_numeric(s):
    return s.isdigit()


def compare(a, b):
    """Compare two parsed semver tuples. Returns -1, 0, or 1."""
    for i in range(3):
        if a[i] < b[i]:
            return -1
        if a[i] > b[i]:
            return 1

    pa, pb = a[3], b[3]
    if not pa and not pb:
        return 0
    if not pa:
        return 1
    if not pb:
        return -1

    for ia, ib in zip(pa, pb):
        na, nb = _is_numeric(ia), _is_numeric(ib)
        if na and nb:
            if int(ia) < int(ib):
                return -1
            if int(ia) > int(ib):
                return 1
        elif na:
            return -1
        elif nb:
            return 1
        else:
            if ia < ib:
                return -1
            if ia > ib:
                return 1

    if len(pa) < len(pb):
        return -1
    if len(pa) > len(pb):
        return 1
    return 0


def satisfies(version, spec):
    """Check whether version satisfies all comparators in spec."""
    parts = spec.split()
    if not parts:
        raise ValueError("empty spec")

    for part in parts:
        if part.startswith('^'):
            target = parse(part[1:])
            if compare(version, target) < 0:
                return False
            upper = (target[0] + 1, 0, 0, (), ())
            if compare(version, upper) >= 0:
                return False
        elif part.startswith('~'):
            target = parse(part[1:])
            if compare(version, target) < 0:
                return False
            upper = (target[0], target[1] + 1, 0, (), ())
            if compare(version, upper) >= 0:
                return False
        elif part.startswith('>='):
            target = parse(part[2:])
            if compare(version, target) < 0:
                return False
        elif part.startswith('<='):
            target = parse(part[2:])
            if compare(version, target) > 0:
                return False
        elif part.startswith('>'):
            target = parse(part[1:])
            if compare(version, target) <= 0:
                return False
        elif part.startswith('<'):
            target = parse(part[1:])
            if compare(version, target) >= 0:
                return False
        elif part in ('=', '=='):
            target = parse(part[1:])
            if compare(version, target) != 0:
                return False
        else:
            raise ValueError(f"unknown comparator: {part!r}")

    return True
