"""csvlite – a small CSV reader/writer using only the standard library."""


def parse(text):
    """Parse CSV text into a list of rows (each row is a list of strings)."""
    if not text:
        return []

    rows = []
    current_row = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                current_field.append(ch)
                i += 1
        else:
            if ch == '"' and not current_field:
                in_quotes = True
                i += 1
            elif ch == ',':
                current_row.append(''.join(current_field))
                current_field = []
                i += 1
            elif ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                current_row.append(''.join(current_field))
                rows.append(current_row)
                current_row = []
                current_field = []
                i += 2
            elif ch == '\n':
                current_row.append(''.join(current_field))
                rows.append(current_row)
                current_row = []
                current_field = []
                i += 1
            else:
                current_field.append(ch)
                i += 1

    # Flush the last row (handles missing final newline).
    if current_field or current_row:
        current_row.append(''.join(current_field))
        rows.append(current_row)

    return rows


def format(rows):
    """Format rows back into CSV text (no trailing newline)."""

    def _needs_quoting(field):
        if not field:
            return False
        if ',' in field or '"' in field or '\r' in field or '\n' in field:
            return True
        if field[0].isspace() or field[-1].isspace():
            return True
        return False

    def _quote(field):
        if not _needs_quoting(field):
            return field
        return '"' + field.replace('"', '""') + '"'

    return '\n'.join(','.join(_quote(f) for f in row) for row in rows)
