"""Exact decimal arithmetic using scaled integers (SCALE = 10000)."""

SCALE = 10000


def _round_half_away(n, d):
    """Round n/d to nearest integer; exact halves go away from zero."""
    if d < 0:
        n, d = -n, -d
    q, r = divmod(n, d)
    if 2 * r > d:
        return q + 1
    elif 2 * r == d:
        return q + 1 if n >= 0 else q
    else:
        return q


def parse(text):
    """Decimal string -> scaled integer. Raises ValueError on bad input."""
    if not text:
        raise ValueError("empty string")

    sign = 1
    i = 0
    if text[0] == '+':
        i = 1
    elif text[0] == '-':
        sign = -1
        i = 1

    rest = text[i:]
    if not rest:
        raise ValueError("no digits")

    dot_pos = rest.find('.')
    if dot_pos == -1:
        int_part = rest
        frac_part = ""
    else:
        int_part = rest[:dot_pos]
        frac_part = rest[dot_pos + 1:]
        if '.' in frac_part:
            raise ValueError("multiple decimal points")

    if int_part and not int_part.isdigit():
        raise ValueError("non-digit characters")
    if frac_part and not frac_part.isdigit():
        raise ValueError("non-digit characters")
    if len(frac_part) > 4:
        raise ValueError("too many decimal places")
    if not int_part and not frac_part:
        raise ValueError("no digits")

    int_val = int(int_part) if int_part else 0
    frac_val = int(frac_part) if frac_part else 0
    frac_val *= 10 ** (4 - len(frac_part))

    return sign * (int_val * SCALE + frac_val)


def format(value):
    """Scaled integer -> string with exactly 4 decimal places."""
    if value < 0:
        sign = "-"
        value = -value
    else:
        sign = ""
    int_part = value // SCALE
    frac_part = value % SCALE
    return f"{sign}{int_part}.{frac_part:04d}"


def add(a, b):
    """Addition of two scaled integers."""
    return a + b


