import math


def _check_nonempty(xs):
    if len(xs) == 0:
        raise ValueError("empty input")


def mean(xs):
    _check_nonempty(xs)
    return sum(xs) / len(xs)


def median(xs):
    _check_nonempty(xs)
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        return float(s[n // 2])
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2.0


def variance(xs, sample=False):
    _check_nonempty(xs)
    n = len(xs)
    if sample and n < 2:
        raise ValueError("sample variance requires at least 2 values")
    m = sum(xs) / n
    ss = sum((x - m) ** 2 for x in xs)
    divisor = (n - 1) if sample else n
    return ss / divisor


def stdev(xs, sample=False):
    return math.sqrt(variance(xs, sample=sample))


def percentile(xs, p):
    _check_nonempty(xs)
    if p < 0 or p > 100:
        raise ValueError("p must be in 0..100")
    s = sorted(xs)
    n = len(s)
    k = (n - 1) * p / 100.0
    lo = int(math.floor(k))
    hi = int(math.ceil(k))
    if lo == hi:
        return float(s[lo])
    return s[lo] + (s[hi] - s[lo]) * (k - lo)


def mode(xs):
    _check_nonempty(xs)
    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1
    max_count = max(counts.values())
    candidates = [x for x, c in counts.items() if c == max_count]
    return min(candidates)


def normalize(xs):
    _check_nonempty(xs)
    m = mean(xs)
    sd = stdev(xs, sample=False)
    if sd == 0:
        raise ValueError("standard deviation is zero")
    return [(x - m) / sd for x in xs]


def covariance(xs, ys, sample=False):
    _check_nonempty(xs)
    if len(xs) != len(ys):
        raise ValueError("mismatched lengths")
    n = len(xs)
    if sample and n < 2:
        raise ValueError("sample covariance requires at least 2 values")
    mx = sum(xs) / n
    my = sum(ys) / n
    ss = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    divisor = (n - 1) if sample else n
    return ss / divisor


def correlation(xs, ys):
    _check_nonempty(xs)
    if len(xs) != len(ys):
        raise ValueError("mismatched lengths")
    cov = covariance(xs, ys, sample=False)
    sx = stdev(xs, sample=False)
    sy = stdev(ys, sample=False)
    if sx == 0 or sy == 0:
        raise ValueError("standard deviation is zero")
    return cov / (sx * sy)
