    return sum(xs) / len(xs)


def median(xs):
    _check_nonempty(xs)
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        return float(s[n // 2])
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2.0


def variance(xs, sample=False):
    _check_nonempty(xs)
    _check_sample_size(xs, sample)
    n = len(xs)
    m = sum(xs) / n
    ss = sum((x - m) ** 2 for x in xs)
    if sample:
        return ss / (n - 1)
    return ss / n


def stdev(xs, sample=False):
    return math.sqrt(variance(xs, sample))


def percentile(xs, p):
    _check_nonempty(xs)
    if p < 0 or p > 100:
        raise ValueError("p must be in 0..100")
    s = sorted(xs)
    n = len(s)
    k = (n - 1) * p / 100.0
    lo = int(math.floor(k))
    hi = int(math.ceil(k))
    if lo == hi:
        return float(s[lo])
    return s[lo] + (s[hi] - s[lo]) * (k - lo)


