"""csvlite – a minimal CSV reader/writer using only the standard library."""


def parse(text):
    """Parse CSV text into a list of rows (each row a list of strings)."""
    if not text:
        return []

    rows = []
    current_row = []
    i = 0
    n = len(text)

    while i < n:
        field, i = _parse_field(text, i, n)
        current_row.append(field)

        if i >= n:
            break

        ch = text[i]
        if ch == ',':
            i += 1
        elif ch == '\r':
            if i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
            rows.append(current_row)
            current_row = []
        elif ch == '\n':
            i += 1
            rows.append(current_row)
            current_row = []

    if current_row:
        rows.append(current_row)

    return rows


def _parse_field(text, i, n):
    """Parse one field starting at index i. Return (field_string, new_index)."""
    if i < n and text[i] == '"':
        # Quoted field
        i += 1  # skip opening quote
        parts = []
        while i < n:
            if text[i] == '"':
                if i + 1 < n and text[i + 1] == '"':
                    parts.append('"')
                    i += 2
                else:
                    i += 1  # skip closing quote
                    break
            else:
                parts.append(text[i])
                i += 1
        return ''.join(parts), i
    else:
        # Unquoted field – read until delimiter or line ending
        start = i
        while i < n and text[i] not in (',', '\n', '\r'):
            i += 1
        return text[start:i], i


def format(rows):
    """Format rows back into CSV text (no trailing newline)."""
    lines = []
    for row in rows:
        fields = []
        for field in row:
            if _needs_quoting(field):
                escaped = field.replace('"', '""')
                fields.append('"' + escaped + '"')
            else:
                fields.append(field)
        lines.append(','.join(fields))
    return '\n'.join(lines)


def _needs_quoting(field):
    """Decide whether a field must be quoted."""
    if not field:
        return False
    if ',' in field or '"' in field or '\r' in field or '\n' in field:
        return True
    if field != field.strip():
        return True
    return False
