"""Exact fixed-point arithmetic using scaled integers (SCALE = 10000)."""

import re

SCALE = 10000

_PATTERN = re.compile(r'[+-]?(?:\d+\.?\d*|\.\d+)')


def _round_half_away(numerator, denominator):
    """Divide numerator by denominator, rounding halves away from zero."""
    if denominator < 0:
        numerator = -numerator
        denominator = -denominator

    quotient = numerator // denominator
    remainder = numerator % denominator

    if remainder * 2 > denominator:
        return quotient + 1
    elif remainder * 2 == denominator:
        if numerator >= 0:
            return quotient + 1
        else:
            return quotient
    else:
        return quotient


def parse(text):
    """Parse a decimal string to a scaled integer.

    Accepts optional leading +/-, optional single '.', at most 4 decimal places.
    '.5' and '5.' are valid. Raises ValueError otherwise.
    """
    if not text:
        raise ValueError("empty string")

    if not _PATTERN.fullmatch(text):
        raise ValueError(f"invalid format: {text!r}")

    sign = -1 if text[0] == '-' else 1
    body = text[1:] if text[0] in '+-' else text

    if '.' in body:
        int_part, frac_part = body.split('.')
        if len(frac_part) > 4:
            raise ValueError("more than 4 decimal places")
        int_val = int(int_part) if int_part else 0
        frac_val = int(frac_part.ljust(4, '0')) if frac_part else 0
        return sign * (int_val * SCALE + frac_val)
    else:
        return sign * int(body) * SCALE


def format(value):
    """Format a scaled integer as a string with exactly 4 decimal places."""
    sign = '-' if value < 0 else ''
    abs_val = abs(value)
    int_part = abs_val // SCALE
    frac_part = abs_val % SCALE
    return f"{sign}{int_part}.{frac_part:04d}"


def add(a, b):
    """Add two scaled integers."""
    return a + b


def sub(a, b):
    """Subtract two scaled integers."""
    return a - b


def mul(a, b):
    """Multiply two scaled integers, rounding halves away from zero."""
    return _round_half_away(a * b, SCALE)


def div(a, b):
    """Divide two scaled integers, rounding halves away from zero.

    Raises ZeroDivisionError when b == 0.
    """
    if b == 0:
        raise ZeroDivisionError("division by zero")
    return _round_half_away(a * SCALE, b)


def to_float(value):
    """Convert a scaled integer to a Python float."""
    return value / SCALE
