"""Half-open interval arithmetic: every interval is [start, end)."""


def merge(intervals):
    """Sort by start, then merge intervals that overlap or merely touch.

    Zero-length intervals (start == end) are dropped.
    Raises ValueError if start > end for any input interval.
    Returns a sorted list of tuples.
    """
    valid = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"start > end: ({start}, {end})")
        if start == end:
            continue
        valid.append((start, end))

    if not valid:
        return []

    valid.sort(key=lambda x: (x[0], x[1]))

    merged = [valid[0]]
    for start, end in valid[1:]:
        prev_start, prev_end = merged[-1]
        if start <= prev_end:
            merged[-1] = (prev_start, max(prev_end, end))
        else:
            merged.append((start, end))

    return merged


def intersect(a, b):
    """Every non-empty overlap of an interval in *a* with one in *b*, merged."""
    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    for s1, e1 in a_merged:
        for s2, e2 in b_merged:
            lo = max(s1, s2)
            hi = min(e1, e2)
            if lo < hi:
                result.append((lo, hi))

    return merge(result)


def subtract(a, b):
    """The parts of *a* not covered by *b*, merged."""
    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    for s1, e1 in a_merged:
        remaining = [(s1, e1)]
        for s2, e2 in b_merged:
            new_remaining = []
            for rs, re in remaining:
                if e2 <= rs or s2 >= re:
                    new_remaining.append((rs, re))
                else:
                    if rs < s2:
                        new_remaining.append((rs, s2))
                    if e2 < re:
                        new_remaining.append((e2, re))
            remaining = new_remaining
        result.extend(remaining)

    return merge(result)


def coverage(intervals):
    """Total length covered, counting overlaps once."""
    merged = merge(intervals)
    return sum(end - start for start, end in merged)


def contains(intervals, point):
    """True when *point* falls in any interval, honouring the half-open rule."""
    for start, end in intervals:
        if start <= point < end:
            return True
    return False
