    sign_x = 1 if X >= 0 else -1
    sign_y = 1 if Y > 0 else -1
    abs_X = abs(X)
    abs_Y = abs(Y)

    q, r = divmod(abs_X, abs_Y)
    if r * 2 >= abs_Y:
        q += 1

    # The sign of the result is sign_x * sign_y
    return (sign_x * sign_y) * q


def to_float(value):
    """the value as a Python float."""
    return value / 10000.0

