def merge(intervals):
    """Sort by start, then merge intervals that overlap or merely touch.
    A zero-length interval (start == end) is dropped.
    Raises ValueError if start > end. Returns a sorted list of tuples.
    """
    if not intervals:
        return []

    valid = []
    for interval in intervals:
        lo, hi = interval
        if lo > hi:
            raise ValueError("start > end")
        if lo < hi:
            valid.append((lo, hi))

    if not valid:
        return []

    # Sort by start time
    valid.sort()

    merged = [list(valid[0])]
    for i in range(1, len(valid)):
        curr_lo, curr_hi = valid[i]
        prev_lo, prev_hi = merged[-1]

        # If current interval overlaps or touches the previous one
        if curr_lo <= prev_hi:
            merged[-1][1] = max(prev_hi, curr_hi)
        else:
            merged.append([curr_lo, curr_hi])

    return [tuple(x) for x in merged]


def intersect(a, b):
    """Every non-empty overlap of an interval in a with one in b, merged."""
    merged_a = merge(a)
    merged_b = merge(b)
    res = []

    i, j = 0, 0
    while i < len(merged_a) and j < len(merged_b):
        a_lo, a_hi = merged_a[i]
        b_lo, b_hi = merged_b[j]

        # Find the intersection of the two intervals
        lo = max(a_lo, b_lo)
        hi = min(a_hi, b_hi)

        if lo < hi:
            res.append((lo, hi))

        # Advance the pointer for the interval that ends first
        if a_hi < b_hi:
            i += 1
        else:
            j += 1

    return res


def subtract(a, b):
    """The parts of a not covered by b, merged."""
    merged_a = merge(a)
    merged_b = merge(b)
    res = []

    for a_lo, a_hi in merged_a:
        current_parts = [(a_lo, a_hi)]
        for b_lo, b_hi in merged_b:
            next_parts = []
            for p_lo, p_hi in current_parts:
                # If b does not overlap with the current part of a
                if b_hi <= p_lo or b_lo >= p_hi:
                    next_parts.append((p_lo, p_hi))
                else:
                    # Overlap exists; split the part
                    # Part before b starts
                    if b_lo > p_lo:
                        next_parts.append((p_lo, b_lo))
                    # Part after b ends
                    if b_hi < p_hi:
                        next_parts.append((b_hi, p_hi))
            current_parts = next_parts
        res.extend(current_parts)

    return res


def coverage(intervals):
    """Total length covered, counting overlaps once."""
    return sum(hi - lo for lo, hi in merge(intervals))


def contains(intervals, point):
    """True when the point falls in any interval, honouring the half-open rule."""
    for lo, hi in intervals:
        if lo <= point < hi:
            return True
    return False
