import math
from collections import Counter

def mean(xs):
    """Arithmetic mean."""
    if not xs:
        raise ValueError("Input sequence cannot be empty.")
    return sum(xs) / len(xs)

def median(xs):
    """Middle value after sorting; for an even count, the mean of the two middle values."""
    if not xs:
        raise ValueError("Input sequence cannot be empty.")
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_xs[mid])
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2.0

def variance(xs, sample=False):
    """Population variance by default, sample variance when sample=True."""
    n = len(xs)
    if n == 0:
        raise ValueError("Input sequence cannot be empty.")
    if sample and n < 2:
        raise ValueError("Sample variance requires at least two values.")

    mu = sum(xs) / n
    sq_diff_sum = sum((x - mu) ** 2 for x in xs)

    if sample:
        return sq_diff_sum / (n - 1)
    else:
        return sq_diff_sum / n

def stdev(xs, sample=False):
    """Square root of the matching variance."""
    return math.sqrt(variance(xs, sample))

def percentile(xs, p):
    """The linear-interpolation-between-closest-ranks method."""
    if not 0 <= p <= 100:
        raise ValueError("Percentile p must be in the range [0, 100].")
    if not xs:
        raise ValueError("Input sequence cannot be empty.")

    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    k = (n - 1) * p / 100.0
    i = math.floor(k)
    j = math.ceil(k)

    if i == j:
        return float(sorted_xs[int(i)])

    return sorted_xs[i] + (k - i) * (sorted_xs[j] - sorted_xs[i])

def mode(xs):
    """The most frequent value; on a tie return the smallest such value."""
    if not xs:
        raise ValueError("Input sequence cannot be empty.")
    counts = Counter(xs)
    max_count = max(counts.values())
    modes = [val for val, count in counts.items() if count == max_count]
    return min(modes)

def normalize(xs):
    """Z-scores, (x - mean) / stdev, using the population stdev."""
    if not xs:
        raise ValueError("Input sequence cannot be empty.")
    mu = mean(xs)
    sigma = stdev(xs, sample=False)
    if sigma == 0:
        raise ValueError("Standard deviation is zero; cannot normalize.")
    return [(x - mu) / sigma for x in xs]

def covariance(xs, ys, sample=False):
    """Population covariance by default; sample uses n - 1."""
    if len(xs) != len(ys):
        raise ValueError("Input sequences must have the same length.")
    n = len(xs)
    if n == 0:
        raise ValueError("Input sequence cannot be empty.")
    if sample and n < 2:
        raise ValueError("Sample covariance requires at least two values.")

    mu_x = mean(xs)
    mu_y = mean(ys)

    cov_sum = sum((xs[i] - mu_x) * (ys[i] - mu_y) for i in range(n))

    if sample:
        return cov_sum / (n - 1)
    else:
        return cov_sum / n

def correlation(xs, ys):
    """Pearson correlation coefficient."""
    return covariance(xs, ys) / (stdev(xs) * stdev(ys))
