    intersections = []
    # Ensure inputs are treated as lists of intervals
    for a_lo, a_hi in a:
        for b_lo, b_hi in b:
            start = max(a_lo, b_lo)
            end = min(a_hi, b_hi)
            if start < end:
                intersections.append((start, end))
    return merge(intersections)


def subtract(a, b):
    """The parts of a not covered by b, merged."""
    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    for a_lo, a_hi in a_merged:
        current_parts = [(a_lo, a_hi)]
        for b_lo, b_hi in b_merged:
            next_parts = []
            for p_lo, p_hi in current_parts:
                # No overlap
                if b_hi <= p_lo or b_lo >= p_hi:
                    next_parts.append((p_lo, p_hi))
                else:
                    # Overlap exists
                    # Part before b
                    if b_lo > p_lo:
                        next_parts.append((p_lo, b_lo))
                    # Part after b
                    if b_hi < p_hi:
                        next_parts.append((b_hi, p_hi))
            current_parts = next_parts
        result.extend(current_parts)
    return merge(result)


def coverage(intervals):
    """Total length covered, counting overlaps once."""
    return sum(hi - lo for lo, hi in merge(intervals))


def contains(intervals, point):
    """True when the point falls in any interval, honouring the half-open rule."""
    for lo, hi in intervals:
        if lo <= point < hi:
            return True
    return False
