import re

def parse(text):
    """
    Parses a semantic version string.
    Returns (major, minor, patch, prerelease, build)
    """
    # Regex for SemVer 2.0.0
    pattern = r'^v?(?P<major>0|[1-9]\d*)\.(?P<minor>0|[1-9]\d*)\.(?P<patch>0|[1-9]\d*)(?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    match = re.match(pattern, text)
    if not match:
        raise ValueError(f"Invalid semantic version: {text}")

    major = int(match.group('major'))
    minor = int(match.group('minor'))
    patch = int(match.group('patch'))

    prerelease_str = match.group('prerelease')
    prerelease = tuple(prerelease_str.split('.')) if prerelease_str else ()

    build_str = match.group('build')
    build = tuple(build_str.split('.')) if build_str else ()

    return (major, minor, patch, prerelease, build)

def compare(a, b):
    """
    Compares two semantic versions.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    """
    # Core parts comparison
    for i in range(3):
        if a[i] != b[i]:
            return (a[i] > b[i]) - (a[i] < b[i])

    # Prerelease comparison
    pre_a = a[3]
    pre_b = b[3]

    if not pre_a and pre_b:
        return 1
    if pre_a and not pre_b:
        return -1
    if not pre_a and not pre_b:
        return 0

    # Both have prerelease identifiers
    for part_a, part_b in zip(pre_a, pre_b):
        if part_a == part_b:
            continue

        a_is_digit = part_a.isdigit()
        b_is_digit = part_b.isdigit()

        if a_is_digit and b_is_digit:
            diff = int(part_a) - int(part_b)
            if diff != 0:
                return (diff > 0) - (diff < 0)
        elif not a_is_digit and not b_is_digit:
            return (part_a > part_b) - (part_a < part_b)
        else:
            # Numeric identifiers always rank lower than alphanumeric
            return -1 if a_is_digit else 1

    # If all shared parts are equal, the one with more identifiers wins
    if len(pre_a) == len(pre_b):
        return 0
    return (len(pre_a) > len(pre_b)) - (len(pre_a) < len(pre_b))

def satisfies(version, spec):
    """
    Checks if a version satisfies a space-separated list of comparators.
    """
    v = parse(version)
    for part in spec.split():
        if part.startswith('^'):
            target = parse(part[1:])
            # ^x.y.z means >=x.y.z and <(x+1).0.0
            next_major = (target[0] + 1, 0, 0, (), ())
            if not (compare(v, target) >= 0 and compare(v, next_major) < 0):
                return False
        elif part.startswith('~'):
            target = parse(part[1:])
            # ~x.y.z means >=x.y.z and <x.(y+1).0
            next_minor = (target[0], target[1] + 1, 0, (), ())
            if not (compare(v, target) >= 0 and compare(v, next_minor) < 0):
                return False
        else:
            # Handle standard operators: >=, <=, >, <, =, ==
            match = re.match(r'(>=|<=|>|<|==|=)(.*)', part)
            if not match:
                raise ValueError(f"Unknown comparator in spec: {part}")
            op, target_str = match.groups()
            target = parse(target_str)
            res = compare(v, target)

            if op == '>=' and res < 0: return False
            if op == '<=' and res > 0: return False
            if op == '>' and res <= 0: return False
            if op == '<' and res >= 0: return False
            if op == '==' and res != 0: return False
            if op == '=' and res != 0: return False

    return True
