import math

def mean(xs):
    """Arithmetic mean."""
    if not xs:
        raise ValueError("Empty input")
    return sum(xs) / len(xs)

def median(xs):
    """Middle value after sorting; for an even count, the mean of the two middle values."""
    if not xs:
        raise ValueError("Empty input")
    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_xs[mid])
    else:
        return (sorted_xs[mid - 1] + sorted_xs[mid]) / 2.0

def variance(xs, sample=False):
    """Population variance by default, sample variance when sample=True."""
    n = len(xs)
    if n == 0:
        raise ValueError("Empty input")
    if sample and n < 2:
        raise ValueError("Sample requires at least 2 values")

    mu = sum(xs) / n
    sum_sq_diff = sum((x - mu) ** 2 for x in xs)

    if sample:
        return sum_sq_diff / (n - 1)
    else:
        return sum_sq_diff / n

def stdev(xs, sample=False):
    """Square root of the matching variance."""
    return math.sqrt(variance(xs, sample))

def percentile(xs, p):
    """The linear-interpolation-between-closest-ranks method."""
    if not 0 <= p <= 100:
        raise ValueError("p must be in 0..100")
    if not xs:
        raise ValueError("Empty input")

    sorted_xs = sorted(xs)
    n = len(sorted_xs)
    k = (n - 1) * (p / 100.0)
    i = math.floor(k)
    j = math.ceil(k)

    if i == j:
        return float(sorted_xs[int(i)])

    # Linear interpolation between sorted_xs[i] and sorted_xs[j]
    return sorted_xs[int(i)] + (k - i) * (sorted_xs[int(j)] - sorted_xs[int(i)])

def mode(xs):
    """The most frequent value; on a tie return the smallest such value."""
    if not xs:
        raise ValueError("Empty input")

    counts = {}
    for x in xs:
        counts[x] = counts.get(x, 0) + 1

    max_count = max(counts.values())
    modes = [val for val, count in counts.items() if count == max_count]
    return min(modes)

def normalize(xs):
    """Z-scores, (x - mean) / stdev, using the population stdev."""
    if not xs:
        raise ValueError("Empty input")
    mu = mean(xs)
    sigma = stdev(xs, sample=False)
    if sigma == 0:
        raise ValueError("Standard deviation is zero; cannot normalize.")
    return [(x - mu) / sigma for x in xs]

def covariance(xs, ys, sample=False):
    """Population by default; sample uses n - 1."""
    if len(xs) != len(ys):
        raise ValueError("Mismatched lengths")
    n = len(xs)
    if n == 0:
        raise ValueError("Empty input")
    if sample and n < 2:
        raise ValueError("Sample requires at least 2 values")

    mu_x = mean(xs)
    mu_y = mean(ys)

    sum_prod_diff = sum((xs[i] - mu_x) * (ys[i] - mu_y) for i in range(n))

    if sample:
        return sum_prod_diff / (n - 1)
    else:
        return sum_prod_diff / n

def correlation(xs, ys):
    """Pearson correlation coefficient."""
    cov = covariance(xs, ys)
    std_x = stdev(xs, sample=False)
    std_y = stdev(xs, sample=False)
    if std_x == 0 or std_y == 0:
        raise ValueError("Standard deviation is zero; correlation undefined.")
    return cov / (std_x * std_y)
